import jax
import jax.numpy as jnp
import jax.experimental.pallas as pl
import jax.experimental.pallas.tpu as pltpu


def _block_size(size, maximum):
    block = min(size, maximum)
    while size % block != 0:
        block -= 1
    return block


def _max_axis1_kernel(x_ref, out_ref):
    row_block = pl.program_id(2)
    block_max = jnp.max(x_ref[0, :, :], axis=0)[None, :]

    @pl.when(row_block == 0)
    def _initialize():
        out_ref[...] = block_max

    @pl.when(row_block != 0)
    def _accumulate():
        out_ref[...] = jnp.maximum(out_ref[...], block_max)


def workload(x):
    batch, rows, columns = x.shape
    row_block = _block_size(rows, 256)
    column_block = _block_size(columns, 512)

    grid = (batch, columns // column_block, rows // row_block)
    grid_spec = pltpu.PrefetchScalarGridSpec(
        num_scalar_prefetch=0,
        grid=grid,
        in_specs=[
            pl.BlockSpec(
                (1, row_block, column_block),
                lambda b, c, r: (b, r, c),
            )
        ],
        out_specs=pl.BlockSpec(
            (1, column_block),
            lambda b, c, r: (b, c),
        ),
    )

    return pl.pallas_call(
        _max_axis1_kernel,
        grid_spec=grid_spec,
        out_shape=jax.ShapeDtypeStruct((batch, columns), x.dtype),
    )(x)

