from jax.experimental import pallas as pl


def _min_reduction_kernel(x_ref, out_ref):
    reduction_tile = pl.program_id(2)
    tile_min = jnp.min(x_ref[0, :, :], axis=0)

    @pl.when(reduction_tile == 0)
    def _initialize():
        out_ref[0, :] = tile_min

