        return (e, k, n)

    def b_map(e, m, n, k):
        del m, k
        return (e * num_n_blocks + n,)

    def out_map(e, m, n, k):
        del k
        return (e, m, n)

    grid_spec = pltpu.PrefetchScalarGridSpec(
        num_scalar_prefetch=0,
        grid=grid,
        in_specs=[
            pl.BlockSpec((1, block_m, block_k), x_map),
            pl.BlockSpec((1, block_k, block_n), w_map),
            pl.BlockSpec((block_n,), b_map),
        ],
        out_specs=pl.BlockSpec((1, block_m, block_n), out_map),
        scratch_shapes=[
            pltpu.VMEM((block_m, block_n), jnp.float32),
        ],
    )

    return pl.pallas_call(
        _up_kernel if is_up else _down_kernel,
        grid_spec=grid_spec,
