                pl.BlockSpec(
                    (hidden2_padded, bn3), lambda m, n, k: (k, n)
                ),
                pl.BlockSpec((bn3,), lambda m, n, k: (n,)),
                pl.BlockSpec((bm, bn3), lambda m, n, k: (m, n)),
            ],
            out_specs=pl.BlockSpec(
                (bm, bn3), lambda m, n, k: (m, n)
