            scratch_shapes=[pltpu.VMEM((bm, bn3), jnp.float32)],
        ),
        out_shape=jax.ShapeDtypeStruct(
            (batch, action_dim), jnp.float32
        ),
    )(h2, w3_padded, b3, action)


def functools_partial_first(state_blocks):
