from jax.experimental.pallas import tpu as pltpu


def _grid_spec(grid, in_specs, out_specs, scratch_shapes=()):
    return pltpu.PrefetchScalarGridSpec(
        num_scalar_prefetch=0,
        grid=grid,
        in_specs=in_specs,
        out_specs=out_specs,
        scratch_shapes=scratch_shapes,
    )


def _mm_dot(a, b):
    return jax.lax.dot_general(
        a,
        b,
        dimension_numbers=(((1,), (0,)), ((), ())),
        preferred_element_type=jnp.float32,
    )


def _ln_kernel(x_ref, g_ref, b_ref, out_ref):
    x = x_ref[...].astype(jnp.float32)
    mean = jnp.mean(x, axis=-1, keepdims=True)
    centered = x - mean
    var = jnp.mean(centered * centered, axis=-1, keepdims=True)
    y = centered * jax.lax.rsqrt(var + 1e-5)
    y = y * g_ref[...].astype(jnp.float32) + b_ref[...].astype(jnp.float32)
    out_ref[...] = y.astype(out_ref.dtype)


def _matmul_kernel(a_ref, b_ref, out_ref, acc_ref):
    k = pl.program_id(2)

    @pl.when(k == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    acc_ref[...] += _mm_dot(a_ref[...], b_ref[...])

    @pl.when(k == pl.num_programs(2) - 1)
    def _finish():
        out_ref[...] = acc_ref[...].astype(out_ref.dtype)


def _proj_kernel(a_ref, w_ref, bias_ref, residual_ref, out_ref, acc_ref):
    k = pl.program_id(2)

    @pl.when(k == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    acc_ref[...] += _mm_dot(a_ref[...], w_ref[...])

    @pl.when(k == pl.num_programs(2) - 1)
    def _finish():
        y = acc_ref[...] + bias_ref[...].astype(jnp.float32)
        y += residual_ref[...].astype(jnp.float32)
        out_ref[...] = y.astype(out_ref.dtype)


def _fc1_kernel(a_ref, w_ref, bias_ref, out_ref, acc_ref):
    k = pl.program_id(2)

    @pl.when(k == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    acc_ref[...] += _mm_dot(a_ref[...], w_ref[...])

    @pl.when(k == pl.num_programs(2) - 1)
    def _finish():
        z = acc_ref[...] + bias_ref[...].astype(jnp.float32)
        z = 0.5 * z * (1.0 + jax.lax.erf(z * 0.7071067811865476))
        out_ref[...] = z.astype(out_ref.dtype)


def _fc2_kernel(a_ref, w_ref, bias_ref, residual_ref, out_ref, acc_ref):
    k = pl.program_id(2)

    @pl.when(k == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    acc_ref[...] += _mm_dot(a_ref[...], w_ref[...])

    @pl.when(k == pl.num_programs(2) - 1)
    def _finish():
        y = acc_ref[...] + bias_ref[...].astype(jnp.float32)
        y += residual_ref[...].astype(jnp.float32)
        out_ref[...] = y.astype(out_ref.dtype)


def _attention_kernel(q_ref, k_ref, v_ref, out_ref, acc_ref, max_ref, sum_ref):
    ki = pl.program_id(2)

    @pl.when(ki == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)
        max_ref[...] = jnp.full(max_ref.shape, -jnp.inf, dtype=jnp.float32)
        sum_ref[...] = jnp.zeros_like(sum_ref)

    q = q_ref[...]
    scores = jax.lax.dot_general(
        q,
        k_ref[...],
        dimension_numbers=(((1,), (1,)), ((), ())),
        preferred_element_type=jnp.float32,
    )
    scores = scores * (q_ref.shape[-1] ** -0.5)

    old_max = max_ref[...]
    new_max = jnp.maximum(old_max, jnp.max(scores, axis=1))
    correction = jnp.exp(old_max - new_max)
    probabilities = jnp.exp(scores - new_max[:, None])
    new_sum = sum_ref[...] * correction + jnp.sum(probabilities, axis=1)

    weighted_values = jax.lax.dot_general(
        probabilities.astype(q.dtype),
        v_ref[...],
        dimension_numbers=(((1,), (0,)), ((), ())),
        preferred_element_type=jnp.float32,
    )
    new_acc = acc_ref[...] * correction[:, None] + weighted_values
    acc_ref[...] = new_acc
    max_ref[...] = new_max
    sum_ref[...] = new_sum

    @pl.when(ki == pl.num_programs(2) - 1)
    def _finish():
        out_ref[...] = (new_acc / new_sum[:, None]).astype(out_ref.dtype)


def _layer_norm(x, gamma, beta):
    rows, channels = x.shape
    block_rows = 128
    return pl.pallas_call(
        _ln_kernel,
        grid_spec=_grid_spec(
            (rows // block_rows,),
            [
                pl.BlockSpec((block_rows, channels), lambda i: (i, 0)),
                pl.BlockSpec((channels,), lambda i: (0,)),
                pl.BlockSpec((channels,), lambda i: (0,)),
            ],
            pl.BlockSpec((block_rows, channels), lambda i: (i, 0)),
        ),
        out_shape=jax.ShapeDtypeStruct(x.shape, x.dtype),
    )(x, gamma, beta)


def _plain_matmul(a, b):
    rows, inner = a.shape
    inner_b, cols = b.shape
    bm, bn, bk = 256, 256, 256
    return pl.pallas_call(
        _matmul_kernel,
        grid_spec=_grid_spec(
            (rows // bm, cols // bn, inner // bk),
            [
                pl.BlockSpec((bm, bk), lambda i, j, k: (i, k)),
                pl.BlockSpec((bk, bn), lambda i, j, k: (k, j)),
            ],
            pl.BlockSpec((bm, bn), lambda i, j, k: (i, j)),
            [pltpu.VMEM((bm, bn), jnp.float32)],
        ),
        out_shape=jax.ShapeDtypeStruct((rows, cols), a.dtype),
    )(a, b)


def _projection(a, w, bias, residual):
    rows, inner = a.shape
    cols = w.shape[1]
    bm, bn, bk = 256, 256, 256
    return pl.pallas_call(
        _proj_kernel,
        grid_spec=_grid_spec(
            (rows // bm, cols // bn, inner // bk),
            [
                pl.BlockSpec((bm, bk), lambda i, j, k: (i, k)),
                pl.BlockSpec((bk, bn), lambda i, j, k: (k, j)),
                pl.BlockSpec((bn,), lambda i, j, k: (j,)),
                pl.BlockSpec((bm, bn), lambda i, j, k: (i, j)),
            ],
            pl.BlockSpec((bm, bn), lambda i, j, k: (i, j)),
            [pltpu.VMEM((bm, bn), jnp.float32)],
        ),
        out_shape=jax.ShapeDtypeStruct((rows, cols), a.dtype),
    )(a, w, bias, residual)


def _fc1(a, w, bias):
    rows, inner = a.shape
    cols = w.shape[1]
    bm, bn, bk = 256, 256, 256
    return pl.pallas_call(
        _fc1_kernel,
        grid_spec=_grid_spec(
            (rows // bm, cols // bn, inner // bk),
            [
                pl.BlockSpec((bm, bk), lambda i, j, k: (i, k)),
                pl.BlockSpec((bk, bn), lambda i, j, k: (k, j)),
                pl.BlockSpec((bn,), lambda i, j, k: (j,)),
            ],
            pl.BlockSpec((bm, bn), lambda i, j, k: (i, j)),
            [pltpu.VMEM((bm, bn), jnp.float32)],
        ),
        out_shape=jax.ShapeDtypeStruct((rows, cols), a.dtype),
    )(a, w, bias)


def _fc2(a, w, bias, residual):
    rows, inner = a.shape
    cols = w.shape[1]
    bm, bn, bk = 256, 256, 256
    return pl.pallas_call(
        _fc2_kernel,
        grid_spec=_grid_spec(
            (rows // bm, cols // bn, inner // bk),
            [
                pl.BlockSpec((bm, bk), lambda i, j, k: (i, k)),
                pl.BlockSpec((bk, bn), lambda i, j, k: (k, j)),
                pl.BlockSpec((bn,), lambda i, j, k: (j,)),
                pl.BlockSpec((bm, bn), lambda i, j, k: (i, j)),
            ],
            pl.BlockSpec((bm, bn), lambda i, j, k: (i, j)),
            [pltpu.VMEM((bm, bn), jnp.float32)],
        ),
        out_shape=jax.ShapeDtypeStruct((rows, cols), a.dtype),
    )(a, w, bias, residual)


def _attention(q, k, v):
    batch_heads, length, head_dim = q.shape
    bq, bk = 256, 256

    def q_map(bh, qi, ki):
        return (bh, qi, 0)

    def k_map(bh, qi, ki):
        return (bh, ki, 0)

    def out_map(bh, qi, ki):
        return (bh, qi, 0)

    return pl.pallas_call(
        _attention_kernel,
        grid_spec=_grid_spec(
            (batch_heads, length // bq, length // bk),
            [
                pl.BlockSpec((bq, head_dim), q_map),
                pl.BlockSpec((bk, head_dim), k_map),
                pl.BlockSpec((bk, head_dim), k_map),
            ],
            pl.BlockSpec((bq, head_dim), out_map),
            [
                pltpu.VMEM((bq, head_dim), jnp.float32),
                pltpu.VMEM((bq,), jnp.float32),
                pltpu.VMEM((bq,), jnp.float32),
            ],
        ),
        out_shape=jax.ShapeDtypeStruct(q.shape, q.dtype),
    )(q, k, v)


def workload(x, ln1_g, ln1_b, w_qkv, w_proj, b_proj,
             ln2_g, ln2_b, w_fc1, b_fc1, w_fc2, b_fc2):
    batch, length, channels = x.shape
    heads = w_qkv.shape[2]
    head_dim = w_qkv.shape[3]
    rows = batch * length

    x2 = x.reshape(rows, channels)
    normalized = _layer_norm(x2, ln1_g, ln1_b)

    qkv = _plain_matmul(
        normalized, w_qkv.reshape(channels, 3 * heads * head_dim)
    )
    qkv = qkv.reshape(batch, length, 3, heads, head_dim)
    qkv = qkv.transpose(2, 0, 3, 1, 4)
    q = qkv[0].reshape(batch * heads, length, head_dim)
    k = qkv[1].reshape(batch * heads, length, head_dim)
    v = qkv[2].reshape(batch * heads, length, head_dim)

    attended = _attention(q, k, v)
    attended = attended.reshape(batch, heads, length, head_dim)
    attended = attended.transpose(0, 2, 1, 3).reshape(
        rows, heads * head_dim
    )

    x2 = _projection(attended, w_proj, b_proj, x2)
    normalized2 = _layer_norm(x2, ln2_g, ln2_b)
    hidden = _fc1(normalized2, w_fc1, b_fc1)
    result = _fc2(hidden, w_fc2, b_fc2, x2)
    return result.reshape(batch, length, channels)

