    key = jax.random.key(0)
    x = jax.random.uniform(key, (CONFIG['batch'], CONFIG['features']), dtype)
    return (x,)


def workload(x):
    rolled = jnp.roll(x[:, :-1], CONFIG['shift'], axis=-1)
    return jnp.concatenate((rolled, x[:, -1:]), axis=-1)

