def _sentence_maxpool_kernel(x_ref, w_ref, b_ref, o_ref, max_ref):
    s_block = pl.program_id(1)

    @pl.when(s_block == 0)
    def _init():
        max_ref[...] = jnp.zeros_like(max_ref)

    for s in range(x_ref.shape[1]):
        y = jnp.dot(
            x_ref[0, s, :, :],
            w_ref[...],
            preferred_element_type=jnp.float32,
        )
        y = jnp.maximum(y + b_ref[...], 0.0)
        max_ref[...] = jnp.maximum(max_ref[...], y)

    @pl.when(s_block == pl.num_programs(1) - 1)
    def _store():
        o_ref.at[0, :, :].set(max_ref[...].astype(o_ref.dtype))


