from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _reduce_kernel(x_ref, out_ref, acc_ref, *, numel):
    k = pl.program_id(1)

    @pl.when(k == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref[...])

    x = x_ref[...].astype(jnp.float32)
    acc_ref[...] += jnp.sum(x * x, axis=1)

    @pl.when(k == pl.num_programs(1) - 1)
    def _finish():
        total = jnp.sum(acc_ref[...], axis=1)
        scale = jax.lax.rsqrt(total / numel + 1e-5)
        out_ref[...] = jnp.broadcast_to(
            scale.reshape(scale.shape[0], 1), out_ref[...].shape
        )


def _scale_kernel(x_ref, scale_ref, out_ref):
    x = x_ref[...].astype(jnp.float32)
    out_ref[...] = (x * scale_ref[...]).astype(out_ref.dtype)


@jax.jit
def workload(x):
    n, c, h, w = x.shape
    rows = c * h

    batch_block = 8 if n % 8 == 0 else n
    row_block = rows
    for candidate in (512, 256, 128, 64, 32, 16, 8):
        if rows % candidate == 0:
            row_block = candidate
            break

    x3 = x.reshape(n, rows, w)
    grid = (n // batch_block, rows // row_block)

    scales = pl.pallas_call(
        functools.partial(_reduce_kernel, numel=rows * w),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=grid,
            in_specs=[
                pl.BlockSpec(
                    (batch_block, row_block, w),
                    lambda i, k: (i, k, 0),
                )
            ],
            out_specs=pl.BlockSpec(
                (batch_block, w), lambda i, k: (i, 0)
            ),
            scratch_shapes=[
                pltpu.VMEM((batch_block, w), jnp.float32)
            ],
        ),
        out_shape=jax.ShapeDtypeStruct((n, w), jnp.float32),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "arbitrary")
        ),
    )(x3)

    scales = scales.reshape(n, 1, w)
    y = pl.pallas_call(
        _scale_kernel,
        grid=grid,
        in_specs=[
            pl.BlockSpec(
                (batch_block, row_block, w),
                lambda i, j: (i, j, 0),
            ),
            pl.BlockSpec(
                (batch_block, 1, w),
                lambda i, j: (i, 0, 0),
            ),
        ],
        out_specs=pl.BlockSpec(
            (batch_block, row_block, w),
            lambda i, j: (i, j, 0),
        ),
        out_shape=jax.ShapeDtypeStruct(x3.shape, x.dtype),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel")
        ),
    )(x3, scales)

