from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _masked_average_pool_kernel(x_ref, mask_ref, out_ref, count_ref):
    b_idx = pl.program_id(2)
    b_steps = pl.num_programs(2)

    @pl.when(b_idx == 0)
    def _initialize():
        out_ref[...] = jnp.zeros_like(out_ref)
        count_ref[...] = jnp.zeros_like(count_ref)

    x = x_ref[0, :, :, :].astype(jnp.float32)
    mask = mask_ref[0, :, :]

    keep = (mask != 0)[:, None, :]
    masked_x = jnp.where(keep, x, jnp.zeros((), jnp.float32))
    out_ref[0, :, :] += jnp.sum(masked_x, axis=0)

    counts = jnp.sum((mask == 1).astype(jnp.float32), axis=0, keepdims=True)
    count_ref[...] += counts

    @pl.when(b_idx == b_steps - 1)
    def _finalize():
        denominator = jnp.maximum(count_ref[...], 1.0)
        out_ref[...] = out_ref[...] / denominator


@jax.jit
def workload(x, x_mask):
    a, b, d, c = x.shape

    # The trailing block dimensions satisfy TPU tiling requirements whenever
    # possible; otherwise use the full input dimension, which is also valid.
    block_b = 16 if b % 16 == 0 else b
    if c % 256 == 0:
        block_c = 256
    elif c % 128 == 0:
        block_c = 128
    else:
        block_c = c

    grid = (a, c // block_c, b // block_b)

    def x_index(a_idx, c_idx, b_idx):
        del c_idx
        return (a_idx, b_idx, 0, 0)

    def mask_index(a_idx, c_idx, b_idx):
        return (a_idx, b_idx, c_idx)

    def out_index(a_idx, c_idx, b_idx):
        del b_idx
        return (a_idx, 0, c_idx)

    grid_spec = pltpu.PrefetchScalarGridSpec(
        num_scalar_prefetch=0,
        grid=grid,
        in_specs=[
            pl.BlockSpec((1, block_b, d, block_c), x_index),
            pl.BlockSpec((1, block_b, block_c), mask_index),
        ],
        out_specs=pl.BlockSpec((1, d, block_c), out_index),
        scratch_shapes=[pltpu.VMEM((1, block_c), jnp.float32)],
    )

    return pl.pallas_call(
        _masked_average_pool_kernel,
        grid_spec=grid_spec,
        out_shape=jax.ShapeDtypeStruct((a, d, c), jnp.float32),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel", "arbitrary")
        ),
    )(x, x_mask)

