    x = x_ref[0]
    top = jnp.maximum(x[0, 0::2, :], x[0, 1::2, :])
    bottom = jnp.maximum(x[1, 0::2, :], x[1, 1::2, :])
    o_ref.at[0, 0][...] = jnp.maximum(top, bottom)


