    n, h, width, c = x.shape
    return pl.pallas_call(
        _pool_kernel,
        grid=(n, h // 2),
        in_specs=[
            pl.BlockSpec((1, 2, width, c), lambda i, j: (i, j, 0, 0))
        ],
        out_specs=pl.BlockSpec(
            (1, 1, width // 2, c), lambda i, j: (i, j, 0, 0)
        ),
        out_shape=jax.ShapeDtypeStruct((n, h // 2, width // 2, c), x.dtype),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel")
        ),
    )(x)


def _upsample_kernel(*args, nrows):
    x_refs = args[:nrows]
    o_ref = args[nrows]
    rows = o_ref.shape[0]
    width = o_ref.shape[1] // 2
    xs = [ref[0].astype(jnp.float32) for ref in x_refs]

    for r in range(rows):
        q = r // 2
        if r % 2 == 0:
            vertical = 0.25 * xs[q] + 0.75 * xs[q + 1]
        else:
            vertical = 0.75 * xs[q + 1] + 0.25 * xs[q + 2]
        even = 0.25 * vertical[:width] + 0.75 * vertical[1:width + 1]
        odd = 0.75 * vertical[1:width + 1] + 0.25 * vertical[2:width + 2]
        row = jnp.reshape(jnp.stack((even, odd), axis=1), (2 * width, -1))
        o_ref.at[r][...] = row.astype(o_ref.dtype)


def _upsample(x):
    n, h, width, c = x.shape
    out_h = 2 * h
    rows = _rows_per_tile(out_h)
    while rows > 1 and (rows % 2 or h % (rows // 2)):
        rows //= 2
    nrows = rows // 2 + 2
    xp = jnp.pad(x, ((0, 0), (1, 1), (1, 1), (0, 0)), mode="edge")
    xr = jnp.reshape(xp, (n * (h + 2), width + 2, c))

    def x_map(i, row_offset):
        first = i * rows
        image = first // out_h
        out_row = first - image * out_h
        return (image * (h + 2) + out_row // 2 + row_offset, 0, 0)

    y = pl.pallas_call(
        functools.partial(_upsample_kernel, nrows=nrows),
        grid=(n * out_h // rows,),
        in_specs=[
            pl.BlockSpec(
                (1, width + 2, c),
                functools.partial(x_map, row_offset=row_offset),
            )
            for row_offset in range(nrows)
        ],
        out_specs=pl.BlockSpec(
            (rows, 2 * width, c), lambda i: (i, 0, 0)
        ),
        out_shape=jax.ShapeDtypeStruct((n * out_h, 2 * width, c), x.dtype),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel",)
        ),
    )(xr, *([xr] * (nrows - 1)))
    return jnp.reshape(y, (n, out_h, 2 * width, c))


def _conv_relu2(x, params):
    x = _conv(x, params[0], params[1], True)
    return _conv(x, params[2], params[3], True)


def _decoder(skip, x, params):
    x = _upsample(x)
    x = jnp.concatenate([skip, x], axis=-1)
    return _conv_relu2(x, params)


@jax.jit
def workload(x, *params):
    x = jnp.transpose(x, (0, 2, 3, 1))
    bef1 = _conv_relu2(x, params[0:4])
    x = _maxpool(bef1)
    bef2 = _conv_relu2(x, params[4:8])
    x = _maxpool(bef2)
    x = _conv_relu2(x, params[8:12])
    x = _decoder(bef2, x, params[12:16])
    x = _decoder(bef1, x, params[16:20])
    x = _conv(x, params[20], params[21], False)
    return jnp.transpose(x, (0, 3, 1, 2))

