def _shift_kernel(x_ref, o_ref, *, tiles_per_group):
    h, w = x_ref.shape[2], x_ref.shape[3]
    group = pl.program_id(1) // tiles_per_group

    @pl.when(group == 0)
    def _left():
        o_ref[:, :, :, 0:1] = x_ref[:, :, :, 0:1]
        o_ref[:, :, :, 1:w] = x_ref[:, :, :, 0:w - 1]

    @pl.when(group == 1)
    def _right():
        o_ref[:, :, :, 0:w - 1] = x_ref[:, :, :, 1:w]
        o_ref[:, :, :, w - 1:w] = x_ref[:, :, :, w - 1:w]

    @pl.when(group == 2)
    def _up():
        o_ref[:, :, 0:1, :] = x_ref[:, :, 0:1, :]
        o_ref[:, :, 1:h, :] = x_ref[:, :, 0:h - 1, :]

    @pl.when(group == 3)
    def _down():
        o_ref[:, :, 0:h - 1, :] = x_ref[:, :, 1:h, :]
        o_ref[:, :, h - 1:h, :] = x_ref[:, :, h - 1:h, :]


def workload(x):
