    quarter_channels = c // 4

    block_channels = 8
    while quarter_channels % block_channels != 0:
        block_channels -= 1
    tiles_per_group = quarter_channels // block_channels

    block_shape = (1, block_channels, h, w)
    return pl.pallas_call(
        functools.partial(
            _shift_kernel, tiles_per_group=tiles_per_group
        ),
        out_shape=jax.ShapeDtypeStruct(x.shape, x.dtype),
        grid=(b, 4 * tiles_per_group),
        in_specs=[
