    key = jax.random.key(0)
    x = jax.random.uniform(key, CONFIG['shape'], dtype)
    return (x,)


def workload(x):
    gelu_pow = x + CONFIG['cubic_coeff'] * x ** 3
    gelu_tanh = jnp.tanh((2.0 / jnp.pi) ** 0.5 * gelu_pow)
    return 0.5 * x * (1.0 + gelu_tanh)

