import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def _arc2_kernel(t_ref, out_ref):
    quarter = pl.program_id(0)
    out_ref[...] = jnp.zeros_like(out_ref)

    @pl.when(quarter == 0)
    def _write_cos():
        angle = t_ref[...].astype(jnp.float32) * jnp.float32(jnp.pi / 2.0)
        out_ref[...] = jnp.cos(angle).astype(out_ref.dtype)

    @pl.when(quarter == 3)
    def _write_sin():
        angle = t_ref[...].astype(jnp.float32) * jnp.float32(jnp.pi / 2.0)
        out_ref[...] = jnp.sin(angle).astype(out_ref.dtype)


def workload(t):
    rows = 1
    for size in t.shape[:-1]:
        rows *= size
    last_dim = t.shape[-1]

    block_rows = min(128, rows)
    while rows % block_rows != 0:
        block_rows -= 1
    num_row_blocks = rows // block_rows

    flat = t.reshape((rows, last_dim))
    result = pl.pallas_call(
        _arc2_kernel,
        grid=(4, num_row_blocks),
        in_specs=[
            pl.BlockSpec(
                (block_rows, last_dim),
                lambda quarter, row_block: (row_block, 0),
            )
        ],
        out_specs=pl.BlockSpec(
            (block_rows, last_dim),
            lambda quarter, row_block: (
                quarter * num_row_blocks + row_block,
                0,
            ),
        ),
        out_shape=jax.ShapeDtypeStruct((4 * rows, last_dim), t.dtype),
    )(flat)
    return result.reshape((4 * t.shape[0],) + t.shape[1:])
