def _channel_pool_kernel(x_ref, out_ref, acc_ref):
    channel = pl.program_id(1)

    @pl.when(channel == 0)
    def _initialize():
        acc_ref[0, :, :] = jnp.full_like(acc_ref[0, :, :], -jnp.inf)
        acc_ref[1, :, :] = jnp.zeros_like(acc_ref[1, :, :])

    value = x_ref[0, 0, :, :]
    acc_ref[0, :, :] = jnp.maximum(acc_ref[0, :, :], value)
    acc_ref[1, :, :] = acc_ref[1, :, :] + value

    @pl.when(channel == pl.num_programs(1) - 1)
    def _store():
        out_ref[0, 0, :, :] = acc_ref[0, :, :].astype(out_ref.dtype)
        mean = acc_ref[1, :, :] / pl.num_programs(1)
        out_ref[0, 1, :, :] = mean.astype(out_ref.dtype)


def workload(x):
    batch, channels, height, width = x.shape

    grid_spec = pltpu.PrefetchScalarGridSpec(
        num_scalar_prefetch=0,
        grid=(batch, channels),
        in_specs=[
            pl.BlockSpec(
                (1, 1, height, width),
                lambda b, c: (b, c, 0, 0),
            )
        ],
        out_specs=pl.BlockSpec(
            (1, 2, height, width),
            lambda b, c: (b, 0, 0, 0),
        ),
        scratch_shapes=[
            pltpu.VMEM((2, height, width), dtype=jnp.float32)
        ],
    )

    return pl.pallas_call(
        _channel_pool_kernel,
        grid_spec=grid_spec,
        out_shape=jax.ShapeDtypeStruct(
            (batch, 2, height, width), dtype=x.dtype
