import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def _style_kernel(x_ref, out_ref):
    step = pl.program_id(1)
    partial = jnp.sum(x_ref[...], axis=(2, 3))
    scale = 1.0 / (
        x_ref.shape[2] * x_ref.shape[3] * pl.num_programs(1)
    )

    @pl.when(step == 0)
    def _initialize():
        out_ref[...] = jnp.zeros_like(out_ref)

    out_ref[...] += partial * scale

    @pl.when(step == pl.num_programs(1) - 1)
    def _normalize():
        style = out_ref[...]
        norm = jnp.sqrt(jnp.sum(style * style, axis=1, keepdims=True))
        out_ref[...] = style / norm


def workload(x0):
    batch, channels, height, width = x0.shape

    # Choose spatial tiles of at most 2**20 elements (4 MiB for float32).
    row_block = max(1, min(height, (2**20) // (channels * width)))
    while height % row_block != 0:
        row_block -= 1

    return pl.pallas_call(
        _style_kernel,
        out_shape=jax.ShapeDtypeStruct((batch, channels), x0.dtype),
        grid=(batch, height // row_block),
        in_specs=[
            pl.BlockSpec(
                (1, channels, row_block, width),
                lambda n, s: (n, 0, s, 0),
            )
        ],
        out_specs=pl.BlockSpec(
            (1, channels),
            lambda n, s: (n, 0),
        ),
    )(x0)

