def _pool_matmul_kernel(x_ref, w_ref, b_ref, out_ref, pool_ref, *, steps):
    spatial_step = pl.program_id(1)
    block_max = jnp.max(x_ref[...], axis=-1)

    @pl.when(spatial_step == 0)
    def _initialize():
        pool_ref[...] = block_max

    @pl.when(spatial_step != 0)
    def _update():
        pool_ref[...] = jnp.maximum(pool_ref[...], block_max)

    @pl.when(spatial_step == steps - 1)
    def _finish():
        result = jnp.dot(
            pool_ref[...],
            w_ref[...],
            preferred_element_type=jnp.float32,
        )
        result = result + b_ref[...].astype(jnp.float32)
        out_ref[...] = result.astype(out_ref.dtype)


@jax.jit
def workload(x, w, b):
    batch, channels, height, width = x.shape
    out_features = w.shape[1]
    spatial = height * width

    if batch % 32 == 0:
        batch_block = 32
    elif batch % 16 == 0:
        batch_block = 16
    elif batch % 8 == 0:
        batch_block = 8
    else:
        batch_block = batch

    if batch_block == 32 and spatial % 128 == 0:
        spatial_block = 128
    elif spatial % 256 == 0:
        spatial_block = 256
    elif spatial % 128 == 0:
        spatial_block = 128
    else:
        spatial_block = spatial

    spatial_steps = spatial // spatial_block
    x_reshaped = x.reshape(batch, channels, spatial)
    b_reshaped = b.reshape(1, out_features)

    return pl.pallas_call(
        functools.partial(_pool_matmul_kernel, steps=spatial_steps),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(batch // batch_block, spatial_steps),
            in_specs=[
                pl.BlockSpec(
                    (batch_block, channels, spatial_block),
                    lambda i, j: (i, 0, j),
                ),
                pl.BlockSpec(
                    (channels, out_features),
                    lambda i, j: (0, 0),
                ),
                pl.BlockSpec(
                    (1, out_features),
                    lambda i, j: (0, 0),
                ),
            ],
            out_specs=pl.BlockSpec(
                (batch_block, out_features),
                lambda i, j: (i, 0),
            ),
            scratch_shapes=[
                pltpu.VMEM((batch_block, channels), x.dtype),
            ],
        ),
        out_shape=jax.ShapeDtypeStruct(
            (batch, out_features), x.dtype
        ),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "arbitrary"),
        ),
    )(x_reshaped, w, b_reshaped)
