from jax.experimental import pallas as pl


def _transe_kernel(e1_ref, r_ref, e2_ref, out_ref):
    diff = (
        e1_ref[0].astype(jnp.float32)
        + r_ref[0].astype(jnp.float32)
        - e2_ref[0].astype(jnp.float32)
    )
    diff_sq = diff * diff
    power_sum = jnp.sum(diff_sq * diff_sq, axis=0, dtype=jnp.float32)
    out_ref[0] = -jnp.sqrt(jnp.sqrt(power_sum))


