    block_h = 16 if height % 16 == 0 else height
    block_w = 128 if width % 128 == 0 else width

    def input_index(b, h, w):
        return (b, 0, h, w)

    def output_index(b, h, w):
        return (b, h, w)

    input_spec = pl.BlockSpec(
        (1, channels, block_h, block_w), input_index
    )
    output_spec = pl.BlockSpec(
        (1, block_h, block_w), output_index
    )

    return pl.pallas_call(
        _transe_kernel,
        out_shape=jax.ShapeDtypeStruct((batch, height, width), e1.dtype),
        in_specs=[input_spec, input_spec, input_spec],
        out_specs=output_spec,
        grid=(batch, height // block_h, width // block_w),
    )(e1, r, e2)
