from jax.experimental.pallas import tpu as pltpu


def _addcoords_kernel(x_ref, out_ref, *, channels, x_dim, y_dim):
    channel = pl.program_id(1)

    @pl.when(channel < channels)
    def _copy_input():
        out_ref[...] = x_ref[...]

    @pl.when(channel == channels)
    def _write_x_coords():
        rows = jax.lax.broadcasted_iota(
            jnp.int32, (1, 1, x_dim, y_dim), 2
        ).astype(jnp.float32)
        coords = rows / (x_dim - 1) * 2.0 - 1.0
        out_ref[...] = coords.astype(out_ref.dtype)

    @pl.when(channel == channels + 1)
    def _write_y_coords():
        cols = jax.lax.broadcasted_iota(
            jnp.int32, (1, 1, x_dim, y_dim), 3
        ).astype(jnp.float32)
        coords = cols / (y_dim - 1) * 2.0 - 1.0
        out_ref[...] = coords.astype(out_ref.dtype)


def workload(input_tensor):
    batch, channels, x_dim, y_dim = input_tensor.shape
    block_shape = (1, 1, x_dim, y_dim)

    return pl.pallas_call(
        lambda x_ref, out_ref: _addcoords_kernel(
            x_ref,
            out_ref,
            channels=channels,
            x_dim=x_dim,
            y_dim=y_dim,
        ),
        out_shape=jax.ShapeDtypeStruct(
            (batch, channels + 2, x_dim, y_dim), input_tensor.dtype
        ),
        grid=(batch, channels + 2),
        in_specs=[
            pl.BlockSpec(
                block_shape,
                lambda b, c: (b, jnp.minimum(c, channels - 1), 0, 0),
            )
        ],
        out_specs=pl.BlockSpec(
            block_shape, lambda b, c: (b, c, 0, 0)
        ),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel")
        ),
    )(input_tensor)
