import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


_PAD = 1
_GROUPS = 4


def _copy_kernel(x_ref, o_ref, sub, block_c, height, width):
    group = (pl.program_id(1) * block_c) // sub

    o_ref[...] = jnp.zeros(o_ref.shape, dtype=o_ref.dtype)

    @pl.when(group == 0)
    def _group_0():
        o_ref[:, :, _PAD:_PAD + height, _PAD:_PAD + width] = x_ref[...]

    @pl.when(group == 1)
    def _group_1():
        o_ref[:, :, :height, _PAD:_PAD + width] = x_ref[...]

    @pl.when(group == 2)
    def _group_2():
        o_ref[:, :, _PAD:_PAD + height, :width] = x_ref[...]

    @pl.when(group == 3)
    def _group_3():
        o_ref[:, :, :height, :width] = x_ref[...]


def workload(x):
    batch, channels, height, width = x.shape
    sub = channels // _GROUPS
    last = channels - (_GROUPS - 1) * sub

    max_block = 8 if x.dtype.itemsize <= 4 else 4
    block_c = min(max_block, sub, last)
    while block_c > 1 and (sub % block_c != 0 or last % block_c != 0):
        block_c -= 1

    out_height = height + _PAD
    out_width = width + _PAD
    out_shape = jax.ShapeDtypeStruct(
        (batch, channels, out_height, out_width), x.dtype
    )

    return pl.pallas_call(
        lambda x_ref, o_ref: _copy_kernel(
            x_ref, o_ref, sub, block_c, height, width
        ),
        grid=(batch, channels // block_c),
        in_specs=[
            pl.BlockSpec(
                (1, block_c, height, width),
                lambda n, c: (n, c, 0, 0),
            )
        ],
        out_specs=pl.BlockSpec(
            (1, block_c, out_height, out_width),
            lambda n, c: (n, c, 0, 0),
        ),
        out_shape=out_shape,
    )(x)
