def _cat_kl_kernel(log_qy_ref, log_py_ref, out_ref):
    log_qy = log_qy_ref[...].astype(jnp.float32)
    log_py = log_py_ref[...].astype(jnp.float32)
    terms = jnp.exp(log_qy) * (log_qy - log_py)
