    else:
        block_h = height

    return pl.pallas_call(
        _cat_kl_kernel,
        out_shape=jax.ShapeDtypeStruct(
            (batch, height, width), log_qy.dtype
        ),
        grid=(batch, height // block_h),
        in_specs=[
            pl.BlockSpec(
                (1, latent, block_h, width),
                lambda b, h: (b, 0, h, 0),
            ),
            pl.BlockSpec(
                (1, latent, block_h, width),
                lambda b, h: (b, 0, h, 0),
