            pl.BlockSpec((bm, bk), x_map),
            pl.BlockSpec((bk, bn), w_map),
            pl.BlockSpec((bn,), b_map),
        ],
        out_specs=pl.BlockSpec((bm, bn), out_map),
        scratch_shapes=[pltpu.VMEM((bm, bn), jnp.float32)],
    )
    return pl.pallas_call(
        functools.partial(_linear_kernel, relu=relu),
        grid_spec=grid_spec,
        out_shape=jax.ShapeDtypeStruct((m, n), out_dtype),
    )(x, w, b)


def workload(x, w1, b1, w2, b2, w3, b3):
    h = x.reshape(-1, w1.shape[0]).astype(jnp.bfloat16)
    h = _linear(h, w1.astype(jnp.bfloat16), b1, True, jnp.bfloat16)
    h = _linear(h, w2.astype(jnp.bfloat16), b2, True, jnp.bfloat16)
    return _linear(h, w3.astype(jnp.bfloat16), b3, False, b3.dtype)
