from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


_SLOPE = 0.01
_TILE = 256


def _finish_tile(acc_ref, b_ref, o_ref):
    y = acc_ref[...] + b_ref[...][None, :].astype(jnp.float32)
    y = jnp.where(y > 0.0, y, y * _SLOPE)
    o_ref[...] = y.astype(o_ref.dtype)


def _dense_kernel(x_ref, w_ref, b_ref, o_ref, acc_ref):
    k = pl.program_id(2)

    @pl.when(k == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    acc_ref[...] += jnp.dot(
        x_ref[...], w_ref[...], preferred_element_type=jnp.float32
    )

    @pl.when(k == pl.num_programs(2) - 1)
    def _store():
        _finish_tile(acc_ref, b_ref, o_ref)


def _dense(x, w, b):
    m, k = x.shape
    n = w.shape[1]
    bm = bn = bk = _TILE
    grid = ((m + bm - 1) // bm, (n + bn - 1) // bn, (k + bk - 1) // bk)

    return pl.pallas_call(
        _dense_kernel,
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=grid,
            in_specs=[
                pl.BlockSpec((bm, bk), lambda i, j, kk: (i, kk)),
                pl.BlockSpec((bk, bn), lambda i, j, kk: (kk, j)),
                pl.BlockSpec((bn,), lambda i, j, kk: (0,)),
            ],
            out_specs=pl.BlockSpec((bm, bn), lambda i, j, kk: (i, j)),
            scratch_shapes=[pltpu.VMEM((bm, bn), dtype=jnp.float32)],
        ),
        out_shape=jax.ShapeDtypeStruct((m, n), x.dtype),
    )(x, w, b)


def _concat_dense(hidden, action, w, b):
    m, hidden_k = hidden.shape
    action_k = action.shape[1]
    total_k, n = w.shape
    bm = bn = bk = _TILE
    hidden_steps = hidden_k // bk
    k_steps = total_k // bk
    grid = ((m + bm - 1) // bm, (n + bn - 1) // bn, k_steps)

    def kernel(h_ref, a_ref, w_ref, b_ref, o_ref, acc_ref):
        k = pl.program_id(2)

        @pl.when(k == 0)
        def _init():
            acc_ref[...] = jnp.zeros_like(acc_ref)

        x = jnp.where(k < hidden_steps, h_ref[...], a_ref[...])
        acc_ref[...] += jnp.dot(
            x, w_ref[...], preferred_element_type=jnp.float32
        )

        @pl.when(k == pl.num_programs(2) - 1)
        def _store():
            _finish_tile(acc_ref, b_ref, o_ref)

    def hidden_map(i, j, k):
        return (i, jnp.minimum(k, hidden_steps - 1))

    def action_map(i, j, k):
        return (i, jnp.maximum(k - hidden_steps, 0))

    return pl.pallas_call(
        kernel,
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=grid,
            in_specs=[
                pl.BlockSpec((bm, bk), hidden_map),
                pl.BlockSpec((bm, bk), action_map),
                pl.BlockSpec((bk, bn), lambda i, j, k: (k, j)),
                pl.BlockSpec((bn,), lambda i, j, k: (0,)),
            ],
            out_specs=pl.BlockSpec((bm, bn), lambda i, j, k: (i, j)),
            scratch_shapes=[pltpu.VMEM((bm, bn), dtype=jnp.float32)],
        ),
        out_shape=jax.ShapeDtypeStruct((m, n), hidden.dtype),
    )(hidden, action, w, b)


def _matvec_kernel(x_ref, w_ref, b_ref, o_ref, acc_ref):
    k = pl.program_id(1)

    @pl.when(k == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    products = (
        x_ref[...].astype(jnp.float32)
        * w_ref[...].astype(jnp.float32)
    )
    acc_ref[...] += jnp.sum(products, axis=1, keepdims=True)

    @pl.when(k == pl.num_programs(1) - 1)
    def _store():
        y = acc_ref[...] + b_ref[...][None, :].astype(jnp.float32)
        o_ref[...] = y.astype(o_ref.dtype)


def _matvec(x, w_t, b):
    m, k = x.shape
    bm = bk = _TILE
    grid = ((m + bm - 1) // bm, (k + bk - 1) // bk)

    return pl.pallas_call(
        _matvec_kernel,
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=grid,
            in_specs=[
                pl.BlockSpec((bm, bk), lambda i, kk: (i, kk)),
                pl.BlockSpec((1, bk), lambda i, kk: (0, kk)),
                pl.BlockSpec((1,), lambda i, kk: (0,)),
            ],
            out_specs=pl.BlockSpec((bm, 1), lambda i, kk: (i, 0)),
            scratch_shapes=[pltpu.VMEM((bm, 1), dtype=jnp.float32)],
        ),
        out_shape=jax.ShapeDtypeStruct((m, 1), x.dtype),
    )(x, w_t, b)


def workload(state, action, w1, b1, w2, b2, w3, b3, w4, b4):
    hidden = _dense(state, w1, b1)
    hidden = _concat_dense(hidden, action, w2, b2)
    hidden = _dense(hidden, w3, b3)
    return _matvec(hidden, w4.T, b4)

