        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(m // t, n // t, k // t),
            in_specs=[
                pl.BlockSpec((t, t), lambda i, j, r: (i, r)),
                pl.BlockSpec((t, t), lambda i, j, r: (r, j)),
                pl.BlockSpec(
                    (1,), lambda i, j, r: (0,), memory_space=pltpu.SMEM
                ),
            ],
            out_specs=pl.BlockSpec((t, t), lambda i, j, r: (i, j)),
            scratch_shapes=[pltpu.VMEM((t, t), _F32)],
        ),
        out_shape=jax.ShapeDtypeStruct((m, n), _F32),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel", "arbitrary")
        ),
    )(a, b, scale)


def _newton_kernel(x_ref, p_ref, old_ref, o_ref, acc_ref, *, precision):
    k = pl.program_id(2)

    @pl.when(k == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    acc_ref[...] += _dot(x_ref[...], p_ref[...], precision)

    @pl.when(k == pl.num_programs(2) - 1)
    def _finish():
        o_ref[...] = jnp.float32(2.0) * old_ref[...] - acc_ref[...]


def _newton_update(x, p, precision):
    b = x.shape[0]
    t = 512
    return pl.pallas_call(
        functools.partial(_newton_kernel, precision=precision),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(b // t, b // t, b // t),
            in_specs=[
                pl.BlockSpec((t, t), lambda i, j, k: (i, k)),
                pl.BlockSpec((t, t), lambda i, j, k: (k, j)),
                pl.BlockSpec((t, t), lambda i, j, k: (i, j)),
            ],
            out_specs=pl.BlockSpec((t, t), lambda i, j, k: (i, j)),
            scratch_shapes=[pltpu.VMEM((t, t), _F32)],
        ),
        out_shape=jax.ShapeDtypeStruct((b, b), _F32),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel", "arbitrary")
        ),
    )(x, p, x)


def _rank_scale_kernel(mean_ref, v_ref, c_ref, *, width):
    mean = mean_ref[...]
    v = v_ref[...]
    denominator = jnp.float32(1.0) + jnp.float32(width) * jnp.sum(
        mean * v, dtype=_F32
    )
    c_ref[0] = jnp.float32(width) / denominator


def _rank_scale(mean, v, width):
    b = mean.shape[0]
    return pl.pallas_call(
        functools.partial(_rank_scale_kernel, width=width),
        grid=(1,),
        in_specs=[
            pl.BlockSpec((b,), lambda i: (0,)),
            pl.BlockSpec((b,), lambda i: (0,)),
        ],
        out_specs=pl.BlockSpec(
            (1,), lambda i: (0,), memory_space=pltpu.SMEM
        ),
        out_shape=jax.ShapeDtypeStruct((1,), _F32),
    )(mean, v)


def _rank_update_kernel(h_ref, vi_ref, vj_ref, c_ref, o_ref):
    vi = vi_ref[...]
    vj = vj_ref[...]
    o_ref[...] = h_ref[...] - c_ref[0] * vi[:, None] * vj[None, :]


def _rank_update(h, v, c):
    b = h.shape[0]
    t = 512
    return pl.pallas_call(
        _rank_update_kernel,
        grid=(b // t, b // t),
        in_specs=[
            pl.BlockSpec((t, t), lambda i, j: (i, j)),
            pl.BlockSpec((t,), lambda i, j: (i,)),
            pl.BlockSpec((t,), lambda i, j: (j,)),
            pl.BlockSpec(
                (1,), lambda i, j: (0,), memory_space=pltpu.SMEM
            ),
        ],
        out_specs=pl.BlockSpec((t, t), lambda i, j: (i, j)),
        out_shape=jax.ShapeDtypeStruct((b, b), _F32),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel")
        ),
    )(h, v, v, c)


def _frob_part_kernel(a_ref, o_ref):
    total = jnp.sum(a_ref[...] * a_ref[...], dtype=_F32)
    # A vector store is required for VMEM.  Dividing by the vector width
    # makes the later sum over all lanes equal the original partial sum.
    value = total / jnp.float32(o_ref.shape[0])
    o_ref[...] = jnp.zeros_like(o_ref) + value


def _frob_parts(a):
    b = a.shape[0]
    t = 512
    nj = b // t
    count = (b // t) * nj
    return pl.pallas_call(
        _frob_part_kernel,
        grid=(b // t, nj),
        in_specs=[pl.BlockSpec((t, t), lambda i, j: (i, j))],
        out_specs=pl.BlockSpec((128,), lambda i, j: (i * nj + j,)),
        out_shape=jax.ShapeDtypeStruct((count * 128,), _F32),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel")
        ),
    )(a)


def _scale_from_parts_kernel(parts_ref, scale_ref):
    norm = jnp.sqrt(jnp.sum(parts_ref[...], dtype=_F32))
    scale_ref[0] = jnp.float32(1.0) / jnp.maximum(
        norm, jnp.float32(1e-30)
    )


def _scale_from_parts(parts):
    p = parts.shape[0]
    return pl.pallas_call(
        _scale_from_parts_kernel,
        grid=(1,),
        in_specs=[pl.BlockSpec((p,), lambda i: (0,))],
        out_specs=pl.BlockSpec(
            (1,), lambda i: (0,), memory_space=pltpu.SMEM
        ),
        out_shape=jax.ShapeDtypeStruct((1,), _F32),
    )(parts)


def _rayleigh_kernel(y_ref, gy_ref, o_ref):
    y = y_ref[...]
    gy = gy_ref[...]
    o_ref[0] = (
        jnp.sum(y * gy, dtype=_F32) / jnp.sum(y * y, dtype=_F32)
    )


def _rayleigh(y, gy):
    b = y.shape[0]
    return pl.pallas_call(
        _rayleigh_kernel,
        grid=(1,),
        in_specs=[
            pl.BlockSpec((b,), lambda i: (0,)),
            pl.BlockSpec((b,), lambda i: (0,)),
        ],
        out_specs=pl.BlockSpec(
            (1,), lambda i: (0,), memory_space=pltpu.SMEM
        ),
        out_shape=jax.ShapeDtypeStruct((1,), _F32),
    )(y, gy)


@jax.jit
def workload(feature):
    b, f = feature.shape

    gram = _gram(feature)
    mean = _row_mean(feature)
    centered = _center_gram(gram, mean, f)

    vector = _init_vector(b)
    for _ in range(12):
        y = _matvec(centered, vector)
        vector, rayleigh = _normalize_power(y, vector)

    inverse = _initial_inverse(rayleigh, b)
    for iteration in range(8):
        precision = _DEFAULT if iteration < 6 else _HIGH
        product = _mm(centered, inverse, precision)
        inverse = _newton_update(inverse, product, precision)

    hm = _matvec(inverse, mean)
    coefficient = _rank_scale(mean, hm, f)
    inverse_original = _rank_update(inverse, hm, coefficient)

    scale = _scale_from_parts(_frob_parts(inverse_original))
    powered = inverse_original
    for _ in range(12):
        powered = _mm_scaled(powered, powered, scale)
        scale = _scale_from_parts(_frob_parts(powered))

    vector = _matvec_scaled(powered, scale, vector)
    gram_vector = _matvec(gram, vector)
    result = _rayleigh(vector, gram_vector)
    return result.reshape(())
