_ALPHA = 4.0


def _exponential_decay_kernel(x_ref, out_ref, state_ref):
    state = x_ref[0, ...].astype(jnp.float32)
    one_minus_alpha = 1.0 - _ALPHA
    for t in range(x_ref.shape[0]):
        x_t = x_ref[t, ...].astype(jnp.float32)
        state = x_t * one_minus_alpha + state * _ALPHA
        out_ref[t, ...] = state.astype(out_ref.dtype)
    state_ref[...] = state.astype(state_ref.dtype)


def workload(x):
    time_steps, dim_1, dim_2, dim_3 = x.shape
    time_block = (time_steps, 1, dim_2, dim_3)
    state_block = (1, dim_2, dim_3)

    def time_index(i):
        return (i, 0, 0, 0)

    def state_index(i):
        return (i, 0, 0)

    return pl.pallas_call(
        _exponential_decay_kernel,
        out_shape=(
            jax.ShapeDtypeStruct(x.shape, x.dtype),
            jax.ShapeDtypeStruct(x.shape[1:], x.dtype),
        ),
        grid=(dim_1,),
        in_specs=[pl.BlockSpec(time_block, time_index)],
        out_specs=[
            pl.BlockSpec(time_block, time_index),
            pl.BlockSpec(state_block, state_index),
        ],
    )(x)

