import jax
import jax.numpy as jnp
from jax import lax
from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _first_linear_relu(state, w1, b1):
    m, k = state.shape
    n = w1.shape[1]
    bm = min(512, m)
    bn = min(512, n)
    bk = min(512, k)

    def kernel(x_ref, w_ref, b_ref, o_ref, acc_ref):
        kk = pl.program_id(2)

        @pl.when(kk == 0)
        def init_acc():
            acc_ref[...] = jnp.zeros(acc_ref.shape, dtype=jnp.float32)

        x = x_ref[...].astype(jnp.bfloat16)
        w = w_ref[...].astype(jnp.bfloat16)
        acc_ref[...] += lax.dot(
            x, w, preferred_element_type=jnp.float32
        )

        @pl.when(kk == pl.num_programs(2) - 1)
        def store_result():
            y = jax.nn.relu(
                acc_ref[...] + b_ref[...].astype(jnp.float32)
            )
            o_ref[...] = y.astype(jnp.bfloat16)

    grid_spec = pltpu.PrefetchScalarGridSpec(
        num_scalar_prefetch=0,
        grid=(m // bm, n // bn, k // bk),
        in_specs=[
            pl.BlockSpec((bm, bk), lambda i, j, kk: (i, kk)),
            pl.BlockSpec((bk, bn), lambda i, j, kk: (kk, j)),
            pl.BlockSpec((bn,), lambda i, j, kk: (j,)),
        ],
        out_specs=pl.BlockSpec((bm, bn), lambda i, j, kk: (i, j)),
        scratch_shapes=[pltpu.VMEM((bm, bn), jnp.float32)],
    )
    return pl.pallas_call(
        kernel,
        grid_spec=grid_spec,
        out_shape=jax.ShapeDtypeStruct((m, n), jnp.bfloat16),
    )(state, w1, b1)


def _combined_linear_output(xs, action, w2, b2, w3, b3, output_dtype):
    m, f1 = xs.shape
    k2, n2 = w2.shape
    q = w3.shape[1]
    bm = min(512, m)
    bn = min(512, n2)
    bk = min(512, k2)
    xs_steps = f1 // bk
    k_steps = k2 // bk

    def kernel(
        xs_ref,
        action_ref,
        w2_ref,
        b2_ref,
        w3_ref,
        b3_ref,
        o_ref,
        acc_ref,
    ):
        jj = pl.program_id(1)
        kk = pl.program_id(2)

        @pl.when((jj == 0) & (kk == 0))
        def init_output():
            o_ref[...] = jnp.broadcast_to(
                b3_ref[...].astype(jnp.float32), o_ref.shape
            )

        @pl.when(kk == 0)
        def init_acc():
            acc_ref[...] = jnp.zeros(acc_ref.shape, dtype=jnp.float32)

        w = w2_ref[...].astype(jnp.bfloat16)

        @pl.when(kk < xs_steps)
        def accumulate_xs():
            x = xs_ref[...].astype(jnp.bfloat16)
            acc_ref[...] += lax.dot(
                x, w, preferred_element_type=jnp.float32
            )

        @pl.when(kk >= xs_steps)
        def accumulate_action():
            x = action_ref[...].astype(jnp.bfloat16)
            acc_ref[...] += lax.dot(
                x, w, preferred_element_type=jnp.float32
            )

        @pl.when(kk == pl.num_programs(2) - 1)
        def project_output():
            h = jax.nn.relu(
                acc_ref[...] + b2_ref[...].astype(jnp.float32)
            )
            partial = lax.dot(
                h.astype(jnp.bfloat16),
                w3_ref[...].astype(jnp.bfloat16),
                preferred_element_type=jnp.float32,
            )
            o_ref[...] += partial

    grid_spec = pltpu.PrefetchScalarGridSpec(
        num_scalar_prefetch=0,
        grid=(m // bm, n2 // bn, k_steps),
        in_specs=[
            pl.BlockSpec(
                (bm, bk),
                lambda i, j, kk: (i, lax.min(kk, xs_steps - 1)),
            ),
            pl.BlockSpec(
                (bm, bk),
                lambda i, j, kk: (i, lax.max(kk - xs_steps, 0)),
            ),
            pl.BlockSpec((bk, bn), lambda i, j, kk: (kk, j)),
            pl.BlockSpec((bn,), lambda i, j, kk: (j,)),
            pl.BlockSpec((bn, q), lambda i, j, kk: (j, 0)),
            pl.BlockSpec((q,), lambda i, j, kk: (0,)),
        ],
        out_specs=pl.BlockSpec((bm, q), lambda i, j, kk: (i, 0)),
        scratch_shapes=[pltpu.VMEM((bm, bn), jnp.float32)],
    )
    return pl.pallas_call(
        kernel,
        grid_spec=grid_spec,
        out_shape=jax.ShapeDtypeStruct((m, q), output_dtype),
    )(xs, action, w2, b2, w3, b3)


def workload(state, action, w1, b1, w2, b2, w3, b3):
    xs = _first_linear_relu(state, w1, b1)
    return _combined_linear_output(
        xs, action, w2, b2, w3, b3, state.dtype
    )
