def _mean_absmax_kernel(x_ref, out_ref, scale_ref, acc_ref, *, steps, reduction_size):
    step = pl.program_id(1)

    @pl.when(step == 0)
    def _init():
        acc_ref[...] = jnp.zeros(acc_ref.shape, dtype=jnp.float32)

    partial = jnp.sum(x_ref[...], axis=1, dtype=jnp.float32)
    acc_ref[...] += partial

    @pl.when(step == steps - 1)
    def _finish():
        mean = (acc_ref[...] / reduction_size).astype(out_ref.dtype)
        out_ref[...] = mean
        scale_ref[...] = jnp.max(
            jnp.abs(mean), axis=-1, keepdims=True
        ).astype(scale_ref.dtype)


def workload(x):
