from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _cumsum_absmax_kernel(x_ref, cs_ref, scale_ref, prefix_ref, absmax_ref):
    j = pl.program_id(1)

    @pl.when(j == 0)
    def _initialize():
        prefix_ref[...] = jnp.zeros_like(prefix_ref)
        absmax_ref[...] = jnp.zeros_like(absmax_ref)

    x = x_ref[...]
    width = x.shape[1]
    triangular = jnp.tril(jnp.ones((width, width), dtype=jnp.float32))
    local = jnp.dot(x, triangular, preferred_element_type=jnp.float32)
    local = local + prefix_ref[...]

    cs_ref[...] = local
    prefix_ref[...] = local[:, width - 1:width]
    block_absmax = jnp.max(jnp.abs(local), axis=1, keepdims=True)
    absmax_ref[...] = jnp.maximum(absmax_ref[...], block_absmax)

    @pl.when(j == pl.num_programs(1) - 1)
    def _store_scale():
        scale_ref[...] = absmax_ref[...]


@jax.jit
def workload(x):
    m, n = x.shape
    bm = 512
    bk = 128
    while bm > 8 and m % bm != 0:
        bm //= 2
    if m % bm != 0:
        bm = m
    if n % bk != 0:
        bk = n

    return pl.pallas_call(
        _cumsum_absmax_kernel,
