    k_index = pl.program_id(1)

    @pl.when(k_index == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    acc_ref[...] += jnp.dot(
        x_ref[...],
        w_ref[...],
        preferred_element_type=jnp.float32,
    )

    @pl.when(k_index == pl.num_programs(1) - 1)
    def _finish():
        scores = acc_ref[...] + b_ref[...][None, :]
        t = transitions_ref.shape[0]
        tile_t = 16 if t % 16 == 0 else t
        for j in range(0, t, tile_t):
            transition_tile = transitions_ref.at[j:j + tile_t, :][...]
            values = scores[:, None, :] + transition_tile[None, :, :]
            out_ref.at[:, j:j + tile_t, :] = values.astype(out_ref.dtype)


def workload(feats, w, b, transitions):
