    @pl.when(k == nsteps - 1)
    def _finish():
        value = acc_ref[...] + b_ref[...]
        if relu:
            value = jnp.maximum(value, 0.0)
        out_ref[...] = value.astype(out_ref.dtype)


def _tile_size(dim, cap, alignment):
    size = min(dim, cap)
    while size < dim:
        if dim % size == 0 and size % alignment == 0:
            return size
        size -= 1
    return dim


def _linear(x, w, bias, *, out_dtype, relu):
    m, k = x.shape
    _, n = w.shape
    bm = _tile_size(m, 512, 16)
    bk = _tile_size(k, 512, 128)
    bn = _tile_size(n, 1024, 128)
    nsteps = k // bk

    return pl.pallas_call(
        functools.partial(_linear_kernel, nsteps=nsteps, relu=relu),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(m // bm, n // bn, nsteps),
            in_specs=[
                pl.BlockSpec((bm, bk), lambda i, j, k_idx: (i, k_idx)),
                pl.BlockSpec((bk, bn), lambda i, j, k_idx: (k_idx, j)),
                pl.BlockSpec((1, bn), lambda i, j, k_idx: (0, j)),
            ],
            out_specs=pl.BlockSpec(
                (bm, bn), lambda i, j, k_idx: (i, j)
            ),
            scratch_shapes=[pltpu.VMEM((bm, bn), jnp.float32)],
        ),
        out_shape=jax.ShapeDtypeStruct((m, n), out_dtype),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel", "arbitrary")
        ),
    )(x, w, bias)


@jax.jit
def workload(x, w_first, b_first, w_last, b_last):
    x = jnp.reshape(x, (x.shape[0], -1))
    hidden = _linear(
        x.astype(jnp.bfloat16),
        w_first.astype(jnp.bfloat16),
        b_first.astype(jnp.float32).reshape(1, b_first.shape[0]),
        out_dtype=jnp.bfloat16,
        relu=True,
    )
    return _linear(
        hidden,
        w_last.astype(jnp.bfloat16),
        b_last.astype(jnp.float32).reshape(1, b_last.shape[0]),
        out_dtype=x.dtype,
        relu=False,
    )
