from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _linear_kernel(x_ref, w_ref, b_ref, out_ref, acc_ref, *, nsteps, leaky):
    k = pl.program_id(2)

    @pl.when(k == 0)
    def _zero_accumulator():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    acc_ref[...] += jnp.dot(
        x_ref[...],
        w_ref[...],
        preferred_element_type=jnp.float32,
    )

    @pl.when(k == nsteps - 1)
    def _finish():
        y = acc_ref[...] + b_ref[...].astype(jnp.float32)
        if leaky:
            y = jnp.where(y >= 0.0, y, y * 0.01)
        out_ref[...] = y.astype(out_ref.dtype)


def _pick_block(size, candidates):
    for candidate in candidates:
        if size % candidate == 0:
            return candidate
    return size


def _linear(x, w, b, *, leaky):
    m, k = x.shape
    _, n = w.shape

    bm = _pick_block(m, (1024, 512, 256, 128))
    bn = _pick_block(n, (512, 256, 128))
    bk = _pick_block(k, (512, 256, 128))
    nsteps = k // bk

    return pl.pallas_call(
        functools.partial(_linear_kernel, nsteps=nsteps, leaky=leaky),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(m // bm, n // bn, nsteps),
            in_specs=[
                pl.BlockSpec((bm, bk), lambda i, j, kk: (i, kk)),
                pl.BlockSpec((bk, bn), lambda i, j, kk: (kk, j)),
                pl.BlockSpec((bn,), lambda i, j, kk: (j,)),
            ],
            out_specs=pl.BlockSpec((bm, bn), lambda i, j, kk: (i, j)),
            scratch_shapes=[pltpu.VMEM((bm, bn), jnp.float32)],
        ),
        out_shape=jax.ShapeDtypeStruct((m, n), x.dtype),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel", "arbitrary")
        ),
    )(x, w, b)


@jax.jit
def workload(state, action, w1, b1, w2, b2, w3, b3):
    xs = _linear(state, w1, b1, leaky=True)
    x = jnp.concatenate([xs, action], axis=1)
    x = _linear(x, w2, b2, leaky=True)
    return _linear(x, w3, b3, leaky=False)
