def _pool_kernel(a_ref, bottom_ref, out_ref):
    a = a_ref[0, ...]
    bottom = bottom_ref[0, ...]
    down = jnp.concatenate((a[1:, ...], bottom), axis=0)
    vertical_left = jnp.maximum(a[:, :, :-1], down[:, :, :-1])
    vertical_right = jnp.maximum(a[:, :, 1:], down[:, :, 1:])
    out_ref[0, ...] = jnp.maximum(vertical_left, vertical_right)


def workload(x):
    n, c, h, w = x.shape
    bh = 8

    xt = jnp.transpose(x, (0, 2, 1, 3))
    xp = jnp.pad(xt, ((0, 0), (0, 1), (0, 0), (0, 1)), mode="edge")

    def a_map(ni, hi):
        return (ni, hi, 0, 0)

    def bottom_map(ni, hi):
        return (ni, (hi + 1) * bh, 0, 0)

    def out_map(ni, hi):
        return (ni, hi, 0, 0)

    y = pl.pallas_call(
        _pool_kernel,
        grid=(n, h // bh),
        in_specs=[
            pl.BlockSpec((1, bh, c, w + 1), a_map),
            pl.BlockSpec((1, 1, c, w + 1), bottom_map),
        ],
        out_specs=pl.BlockSpec((1, bh, c, w), out_map),
        out_shape=jax.ShapeDtypeStruct((n, h, c, w), x.dtype),
    )(xp, xp)

    return jnp.transpose(y, (0, 2, 1, 3))
