def _relative_mse_kernel(im_ref, ref_ref, out_ref):
    pid = pl.program_id(0)

    im = im_ref[...].astype(jnp.float32)
    ref = ref_ref[...].astype(jnp.float32)
    delta = im - ref
    loss = (delta * delta) / (ref * ref + 0.01)
    block_sum = jnp.sum(loss, dtype=jnp.float32)

    @pl.when(pid == 0)
    def _initialize():
        out_ref[0] = 0.0

    out_ref[0] += block_sum

