def _broadcast_sum_kernel(x_ref, out_ref):
    # x_ref: (B, 1, BT, D).  The reference's singleton softmax makes
    # its weights exactly one, leaving this broadcasted batch sum.
    total = jnp.sum(x_ref[...][:, 0], axis=0, dtype=jnp.float32)
    total = total.astype(out_ref.dtype)
    out_ref[...] = jnp.broadcast_to(total[None, None, :, :], out_ref.shape)


def _single_token_kernel(x_ref, out_ref):
    # After squeeze(2) when T == 1, no cross-batch broadcast is introduced.
    total = jnp.sum(x_ref[...][0, :, 0, :], axis=0, dtype=jnp.float32)
    out_ref[...] = total.astype(out_ref.dtype)[None, None, :]


@jax.jit
def workload(x, w1, b1, w2, b2):
    del w1, b1, w2, b2
    b, s, t, d = x.shape

    if t == 1:
        return pl.pallas_call(
            _single_token_kernel,
            out_shape=jax.ShapeDtypeStruct((b, 1, d), x.dtype),
            grid=(b,),
            in_specs=[
                pl.BlockSpec((1, s, 1, d), lambda i: (i, 0, 0, 0))
            ],
            out_specs=pl.BlockSpec((1, 1, d), lambda i: (i, 0, 0)),
            compiler_params=pltpu.CompilerParams(
                dimension_semantics=("parallel",)
            ),
        )(x)

    # Pick a tile that exactly divides T.  A full-T block is also legal
    # for unusual token counts that do not provide an aligned divisor.
    bt = 64
    while bt > 8 and t % bt != 0:
        bt //= 2
    if t % bt != 0:
        bt = t

    return pl.pallas_call(
        _broadcast_sum_kernel,
        out_shape=jax.ShapeDtypeStruct((b, s, t, d), x.dtype),
        grid=(s, t // bt),
        in_specs=[
            pl.BlockSpec(
                (b, 1, bt, d), lambda si, ti: (0, si, ti, 0)
            )
        ],
        out_specs=pl.BlockSpec(
            (b, 1, bt, d), lambda si, ti: (0, si, ti, 0)
        ),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel")
        ),
    )(x)
