import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def _row_block(n, cap):
    if n <= cap:
        return n
    block = cap - (cap % 8)
    while block >= 8 and n % block != 0:
        block -= 8
    return block if block >= 8 else n


def _column_block(n, cap):
    if n <= cap:
        return n
    block = cap - (cap % 128)
    while block >= 128 and n % block != 0:
        block -= 128
    return block if block >= 128 else n


def _normalize_kernel(x_ref, out_ref):
    x = x_ref[...].astype(jnp.float32)
    norm = jnp.sqrt(jnp.sum(x * x, axis=-1, keepdims=True))
    out_ref[...] = (x / norm).astype(out_ref.dtype)


def _matmul_kernel(x_ref, centroids_ref, out_ref):
    out_ref[...] = jax.lax.dot(
        x_ref[...],
        centroids_ref[...],
        preferred_element_type=jnp.float32,
    )


def _normalize_rows(x, row_block):
    rows, features = x.shape
    return pl.pallas_call(
        _normalize_kernel,
        grid=(rows // row_block,),
        in_specs=[
            pl.BlockSpec((row_block, features), lambda i: (i, 0)),
        ],
        out_specs=pl.BlockSpec(
            (row_block, features), lambda i: (i, 0)
        ),
        out_shape=jax.ShapeDtypeStruct(x.shape, jnp.bfloat16),
    )(x)


def workload(x, centroids):
    batch, height, width, features = x.shape
    nclass, centroid_features = centroids.shape
    rows = batch * height * width

    x2d = x.reshape((rows, features))
    normalized_x = _normalize_rows(x2d, _row_block(rows, 128))
    normalized_centroids = _normalize_rows(
        centroids, _row_block(nclass, 128)
    )
    centroids_t = normalized_centroids.transpose(1, 0)

    row_block = _row_block(rows, 512)
    class_block = _column_block(nclass, 256)

    logits = pl.pallas_call(
        _matmul_kernel,
        grid=(rows // row_block, nclass // class_block),
        in_specs=[
            pl.BlockSpec(
                (row_block, features), lambda i, j: (i, 0)
            ),
            pl.BlockSpec(
                (centroid_features, class_block), lambda i, j: (0, j)
            ),
        ],
        out_specs=pl.BlockSpec(
            (row_block, class_block), lambda i, j: (i, j)
        ),
        out_shape=jax.ShapeDtypeStruct(
            (rows, nclass), jnp.float32
        ),
    )(normalized_x, centroids_t)

    return logits.reshape((batch, height, width, nclass))
